head.script:
///////// 1. 변수 및 선언 영역 /////////
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
// mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.trsIdx; // insert, update 구분

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        let arrPar = new Array();
        /***************************************
        opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
        opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
         ***************************************/
        const parentWin = $c.frame.path("../");
        if (parentWin !== undefined) {
            scwin.fn_GetPar = parentWin.fn_GetParBzProcsNo;
            scwin.fn_SetPar = parentWin.fn_SetParBzProcsNo;
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05247.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05247.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnClick = async function(row, colid) {
    try {
        let arrPar = new Array();
        if (scwin.fn_SetPar !== undefined) {
            arrPar[0] = {
                BZ_PROCS_NO: dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO")
            };
            scwin.fn_SetPar(arrPar);
        }
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05247.grd_List_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
// 로그인 ID

/**
 * @method
 * @name listSync
 * @description 상장적격성 실질심사 내역
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let strIsurCd, strIsurNm = "";
    let arrPar = new Array();
    if (scwin.fn_GetPar !== undefined) {
        scwin.fn_GetPar(arrPar);
        strIsurCd = (arrPar.length >= 1 ? arrPar[0] : "");
        strIsurNm = (arrPar.length >= 1 ? arrPar[1] : "");
    }
    txb_ISUR_CD.setValue(strIsurCd);
    txb_COM_NM.setValue(strIsurNm);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/RealInvstg.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
